// Design Ref: §4.2 monitor-alert node 3 — 급락 판정
// Plan SC: 일일 모니터링(방문자/검색유입 전일대비 50%+ 급락 감지)
const staticData = $getWorkflowStaticData('global');

// Run Stats Script가 Vercel API를 호출하는 HTTP Request 노드라 응답 JSON이 이미 $json에 파싱되어 있다.
const today = $input.first().json;
if (today.visitors === undefined || today.searchInflow === undefined) {
  throw new Error('stats API 응답에 visitors/searchInflow가 없음: ' + JSON.stringify(today));
}

const prev = staticData.lastStats || null;

function dropRate(prevVal, curVal) {
  if (!prevVal || prevVal <= 0) return 0;
  return (prevVal - curVal) / prevVal;
}

const visitorsDrop = prev ? dropRate(prev.visitors, today.visitors) : 0;
const inflowDrop = prev ? dropRate(prev.searchInflow, today.searchInflow) : 0;
const maxDrop = Math.max(visitorsDrop, inflowDrop);

// 오늘 수치를 다음 비교 기준으로 저장 (ponytail: 급락 오탐 방지를 위한 2일 연속 확인 등은
// 현재 범위 밖, 운영 중 오탐 많으면 §5 Risks 참조해 추가)
staticData.lastStats = {
  visitors: today.visitors,
  searchInflow: today.searchInflow,
  date: today.date
};

return [{
  json: {
    today,
    previous: prev,
    visitorsDrop,
    inflowDrop,
    isCritical: maxDrop >= 0.5
  }
}];

// Design Ref: §4.2 monitor-alert node 5 — 긴급브레이크 설정
// daily-publish 워크플로우가 이 플래그를 읽고 즉시 종료한다 (§6.1 Error Handling)
// $getWorkflowStaticData('global')는 워크플로우별로 분리되어 daily-publish가 읽을 수 없으므로
// 공유 파일에도 기록한다(같은 서버에서 두 워크플로우가 실행된다는 전제, YAGNI: DB 미도입).
// PROJECT_ROOT 하위에 두는 이유는 daily-publish의 '공유상태 읽기' 노드 주석 참조.
const fs = require('fs');
const path = require('path');
const os = require('os');

const staticData = $getWorkflowStaticData('global');
staticData.emergencyBrake = true;

const sharedStatePath = path.join($env.PROJECT_ROOT || os.tmpdir(), '.n8n-shared-state.json');
let shared = {};
try {
  shared = JSON.parse(fs.readFileSync(sharedStatePath, 'utf8'));
} catch (e) {
  // 파일 없으면 새로 생성
}
shared.emergencyBrake = true;
fs.writeFileSync(sharedStatePath, JSON.stringify(shared));

return $input.all();
